# Describe tasks by their properties, then let the properties suggest methods.
PROPS = ["observable", "deterministic", "sequential", "static", "discrete", "single_agent"]

tasks = {
    "8-puzzle":     dict(observable=True,  deterministic=True,  sequential=True,  static=True,  discrete=True,  single_agent=True),
    "poker":        dict(observable=False, deterministic=False, sequential=True,  static=True,  discrete=True,  single_agent=False),
    "street robot": dict(observable=False, deterministic=False, sequential=True,  static=False, discrete=False, single_agent=False),
}

def suggest(p):
    if all(p[k] for k in PROPS):
        return "exact state-space search"
    if not p["observable"] or not p["deterministic"]:
        return "reason with probabilities; replan as you observe"
    return "search with opponent modelling"

for name, p in tasks.items():
    print(name, "->", suggest(p))
```

Output: 8-puzzle gets exact state-space search; poker and the street robot need probabilistic reasoning and replanning.

